    }
    var merged = listMergedPrs().filter(function (p) {
        return (p.head && p.head.label) === headFilter;
    });
    if (merged.length) {
        return { number: merged[0].number, state: 'MERGED', branch: branch };
    }
    return null;
},

prStatus: function (prNumber) {
