function _prItemFromPr(p) {
    return {
        key: 'pr-' + p.number,
        labels: prLabels(p),
        pr: null,
        issueNumber: linkedIssueNumber(p.body),
        prNumber: p.number,
        draft: !!p.draft,
        branch: _prListBranch(p),
        title: p.title || '',
        author: _prListAuthor(p)
