    };
    var mutexMax = (typeof q.mutexMax === 'number' && isFinite(q.mutexMax))
        ? Math.max(1, Math.floor(q.mutexMax)) : 1;
    var holders = items.filter(holdsMutex);
    if (q.mutexExcludeSelf) {
        items = items.filter(function (candidate) {
